from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, sequence_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = []
    for name in names:
        choices.append([-1] + [v for v in sorted(rows[name])
                               if v not in blocked.get(name, [])
                               and (name not in pins or v == pins[name])])
    best = None

    def check(versions):
        installed = {n for n in names if versions[n] != -1}
        for name, (low, high) in roots.items():
            if name not in installed or not low <= versions[name] <= high:
                return False
        graph = {}
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            if name not in installed:
                return False
            reached.add(name)
            active = []
            for dep in rows[name][versions[name]].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                v = versions[other]
                if v == -1 or not dep["min"] <= v <= dep["max"]:
                    return False
                active.append(other)
                stack.append(other)
            graph[name] = active
        if reached != installed:
            return False
        done, visiting = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            visiting.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in reached)

    def search(i, versions):
        nonlocal best
        if i == len(names):
            if check(versions):
                vector = tuple(versions[n] for n in names)
                if best is None or vector < best:
                    best = vector
            return
        name = names[i]
        for v in choices[i]:
            versions[name] = v
            search(i + 1, versions)

    search(0, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: v for name, v in zip(names, best) if v != -1}}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    usable = [j for j in jobs if j["id"] not in blocked]
    if not mandatory <= {j["id"] for j in usable}:
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    n = len(usable)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [usable[i] for i in range(n) if mask >> i & 1]
        ids = [j["id"] for j in selected]
        if not mandatory <= set(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(j["value"] for j in selected)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    start = data["start"]
    dist = {start_state: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, True, True),
    "component_02": lambda d: _ledger(d, False, False),
    "component_03": lambda d: _ledger(d, True, False),
    "component_04": lambda d: _ledger(d, False, True),
    "component_05": lambda d: _ledger(d, True, True),
    "component_06": _resolver,
    "component_07": _jobs,
    "component_08": _routes,
}
